rade_level": "7º Ano", "competency": "Geografia", "subject": "Geografia", "axis": "CONHE-"}, {"code": "EF07GE06", "name": "Discutir em que medida a produção, a circulação e o consumo de mercadorias Organizar…", "description": "Discutir em que medida a produção, a circulação e o consumo de mercadorias Organizar leitura compartilhada de textos informativos sobre a cadeia produtiva da cana de açúcar no estado de Alagoas.", "grade_level": "7º Ano", "competency": "Geografia", "subject": "Geografia", "axis": "CONHE-"}, {"code": "EF07GE07", "name": "Analisar a influência e o papel das redes de transporte e comunicação na configuração do…", "description": "Analisar a influência e o papel das redes de transporte e comunicação na configuração do território brasileiro. Produzir textos que integrem informações sobre a regionalização do Brasil, ciclos econômicos, formação territorial e suas consequências socioambientais.", "grade_level": "7º Ano", "competency": "Geografia", "subject": "Geografia", "axis": "CONHE-"}, {"code": "EF07GE08", "name": "Estabelecer relações entre os processos de industrialização e inovação tecnológica com as…", "description": "Estabelecer relações entre os processos de industrialização e inovação tecnológica com as transformações socioeconômicas do território brasileiro.", "grade_level": "7º Ano", "competency": "Geografia", "subject": "Geografia", "axis": "CONHE-"}, {"code": "EF07GE09", "name": "Interpretar e elaborar mapas temáticos e históricos, inclusive utilizando tecnologias…", "description": "Interpretar e elaborar mapas temáticos e históricos, inclusive utilizando tecnologias digitais, com informações demográficas e econômicas do Organizar leitura de imagens, mapas, tabelas e gráficos sobre a divisão socioeconômica do Brasil (Amazonas, Centro Sul e Nordeste).", "grade_level": "7º Ano", "competency": "Geografia", "subject": "Geografia", "axis": "CONHE-"}, {"code": "EF07GE10", "name": "Elaborar e interpretar gráficos de barras, gráficos de setores 