INSERT INTO skills (code,name,description,grade_level,competency,subject,axis,municipality_id)
SELECT d.code,d.name,d.description,d.grade_level,d.competency,d.subject,d.axis,(SELECT id FROM muni)
FROM data d
ON CONFLICT (code, municipality_id) DO UPDATE SET
  name=EXCLUDED.name, description=EXCLUDED.description, grade_level=EXCLUDED.grade_level,
  competency=EXCLUDED.competency, subject=EXCLUDED.subject, axis=EXCLUDED.axis;
